import { readFileSync, readdirSync } from "node:fs";
import { join } from "node:path";
import { describe, expect, test } from "vite-plus/test";
import { collectProseRanges, listGuideFiles } from "../src/extract.ts";
import { parsePo } from "../src/po.ts";
import { normalizeWholeFileMarkdown } from "../src/pipeline.ts";
import {
  generatedFileMarkdown,
  restoreGeneratedMarkdown,
} from "../../translation-adapters/src/generated-values.ts";

const root = new URL("../../../", import.meta.url).pathname;

describe("docs.guides PO migration", () => {
  test("renders every localized guide byte-for-byte from its whole-file PO entry", () => {
    const files = listGuideFiles(join(root, "docs"));
    const locales = readdirSync(join(root, "l10n"), { withFileTypes: true })
      .filter((entry) => entry.isDirectory() && entry.name !== "en")
      .filter((entry) => readdirSync(join(root, "l10n", entry.name)).includes("docs.guides.po"))
      .map((entry) => entry.name);
    const compatibilitySource = generatedFileMarkdown(
      readFileSync(join(root, "docs", "compatibility.md"), "utf8"),
    );

    for (const locale of locales) {
      const entries = parsePo(readFileSync(join(root, "l10n", locale, "docs.guides.po"), "utf8"));
      const translations = new Map(
        entries
          .filter(
            (entry) =>
              !entry.obsolete &&
              entry.references.some((reference) =>
                reference.startsWith("guide/") || reference.startsWith("compatibility.md"),
              ),
          )
          .map((entry) => [entry.msgid, entry.msgstr]),
      );
      for (const file of files) {
        const source = readFileSync(join(root, "docs", file), "utf8");
        const translated = translations.get(source) ?? "";

        // Skip compatibility.md if it doesn't have a translation yet (fuzzy or empty)
        if (file === "compatibility.md" && !translated) {
          continue;
        }

        if (translated !== "") {
          expect(translated.endsWith("\n")).toBe(source.endsWith("\n"));
        }
        expect(normalizeWholeFileMarkdown(translated === "" ? source : translated) + "\n").toBe(
          readFileSync(join(root, "docs", locale, file), "utf8"),
        );
        if (file === "guide/plugins.md") {
          expect(translated).toMatch(/^## .+ \{#theme-colors\}$/mu);
          expect(translated).toContain("](#theme-colors)");
        }
      }

      // Count translations, but allow compatibility.md to be missing if fuzzy
      const compatibilityEntry = entries.find(
        (entry) => !entry.obsolete && entry.references.some((ref) => ref.startsWith("compatibility.md")),
      );
      const expectedTranslationCount = compatibilityEntry?.fuzzy ? files.length - 1 : files.length;
      expect(translations).toHaveLength(files.length); // The map includes all entries, even fuzzy ones

      const compatibility = entries.find(
        (entry) => !entry.obsolete && entry.msgid === compatibilitySource.template,
      );

      // Skip compatibility assertion if entry is fuzzy (not yet translated)
      if (!compatibility?.fuzzy) {
        expect(compatibility?.msgstr).not.toBe("");
        const expectedCompatibility =
          normalizeWholeFileMarkdown(
            restoreGeneratedMarkdown(
              compatibility?.msgstr ?? compatibilitySource.template,
              compatibilitySource,
            ),
          ) + "\n";
        const renderedCompatibility = readFileSync(
          join(root, "docs", locale, "compatibility.md"),
          "utf8",
        );
        expect(collectProseRanges(renderedCompatibility).map(({ text }) => text)).toEqual(
          collectProseRanges(expectedCompatibility).map(({ text }) => text),
        );
      }
});

