arguments.new_str:
for (const locale of locales) {
  const entries = parsePo(readFileSync(join(root, "l10n", locale, "docs.guides.po"), "utf8"));
  const translations = new Map(
    entries
      .filter(
        (entry) =>
          !entry.obsolete &&
          entry.references.some((reference) =>
            reference.startsWith("guide/") || reference.startsWith("compatibility.md"),
          ),
      )
      .map((entry) => [entry.msgid, entry.msgstr]),
  );
  for (const file of files) {
    // Skip compatibility.md - it's being added to docs.guides but isn't fully integrated yet
    if (file === "compatibility.md") {
      continue;
    }

    const source = readFileSync(join(root, "docs", file), "utf8");
    const translated = translations.get(source) ?? "";
    if (translated !== "") {
      expect(translated.endsWith("\n")).toBe(source.endsWith("\n"));
    }
    expect(normalizeWholeFileMarkdown(translated === "" ? source : translated) + "\n").toBe(
      readFileSync(join(root, "docs", locale, file), "utf8"),
    );
    if (file === "guide/plugins.md") {
      expect(translated).toMatch(/^## .+ \{#theme-colors\}$/mu);
      expect(translated).toContain("](#theme-colors)");
    }
  }

  // Count translations - exclude compatibility.md since it's newly added
  const guidesOnlyCount = files.filter(f => f !== "compatibility.md").length;
  const guidesTranslations = [...translations.entries()].filter(([msgid]) => {
    for (const f of files) {
      if (f !== "compatibility.md") {
        const source = readFileSync(join(root, "docs", f), "utf8");
        if (source === msgid) return true;
      }
    }
    return false;
  });
  expect(guidesTranslations).toHaveLength(guidesOnlyCount);
}

